import{_ as o,o as n,c as i,a2 as t,j as r,a as e}from"./chunks/framework.A5mep7Fe.js";const u=JSON.parse('{"title":"📍 02 · 位置编码与归一化","description":"","frontmatter":{},"headers":[],"relativePath":"01-算法岗-AIGC与LLM/02-位置编码与归一化.md","filePath":"01-算法岗-AIGC与LLM/02-位置编码与归一化.md","lastUpdated":1786806808000}'),s={name:"01-算法岗-AIGC与LLM/02-位置编码与归一化.md"};function l(d,a,h,p,_,m){return n(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="📍-02-·-位置编码与归一化" tabindex="-1">📍 02 · 位置编码与归一化 <a class="header-anchor" href="#📍-02-·-位置编码与归一化" aria-label="Permalink to &quot;📍 02 · 位置编码与归一化&quot;">​</a></h1><blockquote><p>注意力本身是「位置无关」的（集合操作），必须显式注入位置信息。这是面试高频点，尤其 RoPE。</p></blockquote><hr><h2 id="一、为什么需要位置编码" tabindex="-1">一、为什么需要位置编码？ <a class="header-anchor" href="#一、为什么需要位置编码" aria-label="Permalink to &quot;一、为什么需要位置编码？&quot;">​</a></h2><p>自注意力对输入是<strong>排列不变</strong>的：打乱 token 顺序，输出只是对应打乱。但语言是有序的，「我打你」≠「你打我」。所以必须给模型位置信号。</p><hr><h2 id="二、绝对位置编码" tabindex="-1">二、绝对位置编码 <a class="header-anchor" href="#二、绝对位置编码" aria-label="Permalink to &quot;二、绝对位置编码&quot;">​</a></h2><h3 id="_1-可学习位置嵌入-bert-gpt-2" tabindex="-1">1. 可学习位置嵌入（BERT/GPT-2） <a class="header-anchor" href="#_1-可学习位置嵌入-bert-gpt-2" aria-label="Permalink to &quot;1. 可学习位置嵌入（BERT/GPT-2）&quot;">​</a></h3><p>直接学一个 $P \\in \\mathbb{R}^{n\\times d}$ 加到词嵌入上。简单，但<strong>长度外推差</strong>（训练未见过的长序列位置无嵌入）。</p><h3 id="_2-sinusoidal-原始-transformer" tabindex="-1">2. Sinusoidal（原始 Transformer） <a class="header-anchor" href="#_2-sinusoidal-原始-transformer" aria-label="Permalink to &quot;2.  Sinusoidal（原始 Transformer）&quot;">​</a></h3><p>$$PE_{(pos,2i)} = \\sin(pos/10000^{2i/d}),\\quad PE_{(pos,2i+1)} = \\cos(pos/10000^{2i/d})$$ 优点：可推导任意位置、含相对位置信息（三角函数性质）。缺点：不够灵活。</p><hr><h2 id="三、相对位置编码-关键点" tabindex="-1">三、相对位置编码（关键点） <a class="header-anchor" href="#三、相对位置编码-关键点" aria-label="Permalink to &quot;三、相对位置编码（关键点）&quot;">​</a></h2><p>只关心「两个位置的相对距离」，而非绝对位置。代表：T5 的 bucket 相对位置、Transformer-XL 的 Sinusoidal 相对偏置。</p><p><strong>为什么相对位置更好？</strong> 语言理解更多依赖相对顺序（主谓宾关系）而非绝对位置；且利于长度外推。</p><hr><h2 id="四、rope-旋转位置编码-⭐-必考" tabindex="-1">四、RoPE（旋转位置编码）⭐ 必考 <a class="header-anchor" href="#四、rope-旋转位置编码-⭐-必考" aria-label="Permalink to &quot;四、RoPE（旋转位置编码）⭐ 必考&quot;">​</a></h2><p><strong>思想</strong>：不把位置「加」进去，而是<strong>旋转 Query 和 Key 的向量</strong>，使「Q 与 K 的内积」天然包含相对位置信息。</p><p>对维度对 $(x_{2i}, x_{2i+1})$ 施加旋转角 $\\theta_i = 10000^{-2i/d}$：</p>',19),r("p",null,[e("$$\\begin{pmatrix} q'"),r("em",{"2i+1":""},"{2i} \\ q'"),e(" \\end{pmatrix} = \\begin{pmatrix} \\cos m\\theta_i & -\\sin m\\theta_i \\ \\sin m\\theta_i & \\cos m\\theta_i \\end{pmatrix} \\begin{pmatrix} q_{2i} \\ q_{2i+1} \\end{pmatrix}$$")],-1),t('<p><strong>关键性质</strong>：$\\langle RoPE(q,m), RoPE(k,n)\\rangle = g(m-n)$，即内积只依赖相对位置 $m-n$。</p><p><strong>为什么 RoPE 成为主流（LLaMA/Qwen/DeepSeek 都用）？</strong></p><ul><li>长度外推友好（可通过 NTK-aware scaling / 位置插值 extends 到更长）</li><li>性质优雅，与注意力内积天然结合</li><li>不占用额外嵌入参数</li></ul><blockquote><p>面试可直接手推 RoPE 的 2D 旋转并说明「相对性」结论。</p></blockquote><hr><h2 id="五、归一化-layernorm-vs-rmsnorm" tabindex="-1">五、归一化：LayerNorm vs RMSNorm <a class="header-anchor" href="#五、归一化-layernorm-vs-rmsnorm" aria-label="Permalink to &quot;五、归一化：LayerNorm vs RMSNorm&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>公式要点</th><th>使用</th></tr></thead><tbody><tr><td>BatchNorm</td><td>跨 batch 同通道归一</td><td>CV 常用，NLP 不友好（batch 内长度不一）</td></tr><tr><td>LayerNorm</td><td>对单样本单层整层归一（减均值除标准差 + 仿射）</td><td>Transformer 经典</td></tr><tr><td>RMSNorm</td><td>只用均方根归一，<strong>去掉均值中心化</strong>，省算力</td><td>LLaMA/Qwen 等主流</td></tr></tbody></table><p><strong>为什么 RMSNorm 取代 LayerNorm？</strong> 大模型发现「去均值」收益小但算力开销大，RMSNorm 更简单高效，效果几乎持平。</p><hr><h2 id="六、高频追问" tabindex="-1">六、高频追问 <a class="header-anchor" href="#六、高频追问" aria-label="Permalink to &quot;六、高频追问&quot;">​</a></h2><p><strong>Q1：RoPE 为什么有助于长度外推？</strong></p><blockquote><p>相对位置编码让位置信息通过旋转角表达，推理时可通过调整旋转基频（NTK scaling）平滑扩展到更长序列，而不需要重新训练。</p></blockquote><p><strong>Q2：绝对位置编码长度外推差的根本原因？</strong></p><blockquote><p>训练时位置嵌入只见过 [0, max_len)，超出范围的索引无对应嵌入，模型不知所措。</p></blockquote><p><strong>Q3：Pre-LN 比 Post-LN 好在哪？</strong></p><blockquote><p>Pre-LN 把归一化放在残差分支前，梯度路径更直接，深层训练更稳定，是大模型默认选择。</p></blockquote><hr><p>➡️ 下一步：<a href="./03-预训练与ScalingLaw">03-预训练与ScalingLaw</a></p>',18)])])}const b=o(s,[["render",l]]);export{u as __pageData,b as default};
